The function `openPort` allows you to specify the protocol ("tcp" or "udp") and the port number. It creates a socket, binds it to the specified port, and listens for incoming connections (for TCP). For UDP, it just binds the socket to the port.

```cpp
#include <iostream>
#include <string>
#include <cstring>      // For memset
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>     // For close()

int openPort(const std::string& protocol, int port) {
    int sockfd;
    int opt = 1;
    struct sockaddr_in addr;

    // Create socket
    if (protocol == "tcp") {
        sockfd = socket(AF_INET, SOCK_STREAM, 0);
    } else if (protocol == "udp") {
        sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    } else {
        std::cerr << "Unsupported protocol: " << protocol << std::endl;
        return -1;
    }

    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    // Set socket options to reuse address and port
    if (setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(sockfd);
        return -1;
    }

    // Bind socket to the specified port on all interfaces
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(port);

    if (bind(sockfd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(sockfd);
        return -1;
    }

    if (protocol == "tcp") {
        // Listen for incoming connections
        if (listen(sockfd, 5) < 0) {
            perror("listen");
            close(sockfd);
            return -1;
        }
        std::cout << "TCP port " << port << " is open and listening." << std::endl;
    } else {
        std::cout << "UDP port " << port << " is open and bound." << std::endl;
    }

    // Return the socket file descriptor so the caller can accept connections or receive data
    return sockfd;
}

int main() {
    int tcpSock = openPort("tcp", 8080);
    if (tcpSock < 0) {
        std::cerr << "Failed to open TCP port." << std::endl;
        return 1;
    }

    int udpSock = openPort("udp", 9090);
    if (udpSock < 0) {
        std::cerr << "Failed to open UDP port." << std::endl;
        close(tcpSock);
        return 1;
    }

    // For demonstration, just sleep to keep the ports open
    std::cout << "Press Enter to close sockets and exit..." << std::endl;
    std::cin.get();

    close(tcpSock);
    close(udpSock);

    return 0;
}
```

### Explanation:
- The function `openPort` takes a protocol string ("tcp" or "udp") and a port number.
- It creates a socket accordingly.
- Sets socket options to reuse the address.
- Binds the socket to the specified port on all network interfaces.
- For TCP, it calls `listen` to accept incoming connections.
- Returns the socket file descriptor so the caller can manage it (accept connections, receive data, or close it).
- The `main` function demonstrates opening TCP port 8080 and UDP port 9090, then waits for user input before closing the sockets.

### Notes:
- This code is for Unix-like systems. For Windows, you need to include `<winsock2.h>`, initialize Winsock with `WSAStartup`, and use `closesocket` instead of `close`.
- Running this program may require administrative privileges depending on the port number and OS security settings.
